//! ↩️ Actual Store and Job custody authors canonical edit-order transitions without changing visible roots.
use crate::*;
use store::os_store::original_history_transitions::OriginalHistoryTransitionBatch as Source;
use store::os_spr::{HistoryTransitionEditMode as Mode,HistoryTransitionEditsView as View};
pub(super) fn exercise(store:&store::ConfigStore<State,Mutation>,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){let ids=vec![store.parts_ref().log.envelope.vcs.edits.get(0).unwrap().mutation_meta[0].mutation_id.as_ref().unwrap().clone()];let generation=store.generation();let revision=store.content_revision();let count=store.parts_ref().log.envelope.transitions.len();for mode in [Mode::Revert,Mode::Reinstate]{let view=View{mode,mutation_ids:&ids};for cut in [0,1,8,32,64,128,usize::MAX]{let mut owner=None;let d=Source::birth_demands();assert!(d.copy_bytes<=32768&&d.capacity_bytes<=16<<20);let birth=RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.max(TURN.maximum_copy_bytes),maximum_capacity_bytes:d.capacity_bytes.max(TURN.maximum_capacity_bytes),..TURN};for axis in [0,1,2,4]{let mut denied=birth;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=d.copy_bytes-1,2=>denied.maximum_capacity_bytes=d.capacity_bytes-1,_=>denied.maximum_depth=0};turn(caller,decoder,denied,|cx|{assert!(!Source::admit_edits(store,&view,cx,&mut owner)?);Ok(())});assert!(owner.is_none());}turn(caller,decoder,birth,|cx|{assert!(Source::admit_edits(store,&view,cx,&mut owner)?);Ok(())});let source=owner.as_mut().unwrap();let mut foreign_decoder=OriginalJobDecodeOwner::empty();turn(caller,&mut foreign_decoder,TURN,|cx|{assert!(source.advance_edits(store,&view,cx).is_err());Ok(())});assert!(foreign_decoder.terminal_is_empty());let foreign=View{mode:match mode{Mode::Revert=>Mode::Reinstate,Mode::Reinstate=>Mode::Revert},mutation_ids:&ids};turn(caller,decoder,TURN,|cx|{assert!(source.advance_edits(store,&foreign,cx).is_err());Ok(())});let mut ready=false;for index in 0..262144{if index==cut{break}ready=turn(caller,decoder,TURN,|cx|source.advance_edits(store,&view,cx));assert_eq!(store.generation(),generation);assert_eq!(store.content_revision(),revision);assert_eq!(store.parts_ref().log.envelope.transitions.len(),count);if ready{break}assert!(index<262143);}if cut==usize::MAX{assert!(ready);let mut output=None;turn(caller,decoder,TURN,|cx|{assert!(source.take(cx,&mut output)?);Ok(())});let output=output.unwrap();assert!(output.applies_to_head);assert!(output.branch.is_none());assert_eq!(output.envelopes.len(),1);let envelope=&output.envelopes[0];assert_eq!(envelope.dependencies,ids);assert!(envelope.target.is_empty());let decoded=store::os_spr::history_transition_from_envelope(envelope).unwrap().unwrap();match (&decoded,mode){(store::os_spr::HistoryTransition::Revert{mutation_ids},Mode::Revert)|(store::os_spr::HistoryTransition::Reinstate{mutation_ids},Mode::Reinstate)=>assert_eq!(mutation_ids,&ids),_=>panic!("original edit event must preserve its canonical kind")};publication::close_typed(decoded,caller,decoder);publication::close_typed(output,caller,decoder);}for index in 0..262144{if source.terminal_is_empty(){break}let d=source.close_demands(4096).unwrap();let closing=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};turn(caller,decoder,closing,|cx|cx.with_original_retirement(|cx|source.close_step(cx)));assert!(index<262143);}assert!(source.terminal_is_empty());turn(caller,decoder,TURN,|cx|cx.with_original_retirement(|cx|{let d=RetirementDemand{copy_bytes:size_of::<Option<Box<Source>>>(),release_bytes:size_of::<Source>(),depth:1,..Default::default()};close_original_retained_step(cx,d,|_|{drop(owner.take());Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));}}}
